{
  "description": "A large quadrupedal creature shown in right-facing profile standing on a plain light background. The body, head, legs and small rear tuft are covered in dense, shaggy brown fur that is darker on the legs and lighter on the face and underside. The head is broad with a blunt snout, black nostrils, small dark eyes, a slightly open mouth, and two small rounded furry ears on top. Two dark, smooth, pointed horns project from the face, a large forward-curving horn on the tip of the snout and a much smaller horn on the forehead between the eyes. The entire back from behind the neck to the rump is covered by a large, glossy, dark brown domed shell divided into a smooth anterior section over the shoulders and a larger posterior section with fine parallel longitudinal ridges, with a visible seam between them and a segmented lower margin. The animal stands on four thick muscular legs ending in broad paws with long curved claws, and a small furry tail tuft is visible at the rear beneath the edge of the shell.",
  "parts": [
    {
      "part": "head",
      "looks_like": "broad bear-like head covered in thick brown fur with a blunt snout, black nose, small dark eyes and a closed mouth showing a hint of the lower lip",
      "where": "at the anterior end of the body, facing to the right"
    },
    {
      "part": "horns",
      "looks_like": "two dark gray-black smooth pointed horns: a large long horn curving slightly forward and upward on the tip of the snout and a small short pointed horn centered on the forehead between the eyes",
      "where": "on the front of the head, one on the nose tip and one between the eyes"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded ears covered in fluffy brown fur with slightly darker edges",
      "where": "on the top sides of the head, one more forward and one slightly behind"
    },
    {
      "part": "legs",
      "looks_like": "four thick, heavily muscled legs covered in long shaggy dark brown fur, with visible joints and bulk",
      "where": "under the body, two forelegs beneath the chest and two hind legs beneath the hips"
    },
    {
      "part": "feet",
      "looks_like": "four large broad paws with dark pads and five prominent light-tan curved claws on each front paw and similar claws on the hind paws",
      "where": "at the distal ends of each leg, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "a small short tuft of brown fur",
      "where": "at the extreme posterior of the body, protruding slightly from under the lower rear edge of the shell on the left side of the image"
    },
    {
      "part": "shell",
      "looks_like": "a large glossy dark brown domed carapace with a smooth reflective surface, divided into a smaller smooth anterior dome over the shoulders and a larger posterior dome with fine parallel longitudinal ridges and a distinct transverse seam between them",
      "where": "covering the entire dorsal surface from the base of the neck to the rump, sitting on top of the fur"
    },
    {
      "part": "plates",
      "looks_like": "a continuous row of small rectangular dark brown marginal plates with visible sutures, forming a segmented border",
      "where": "along the lower perimeter of the shell, encircling the posterior and lateral edges"
    }
  ],
